import {visibleFields} from './attribute-filter.js?v=20261015-template';
import {parseGlobalIds,globalIdWhere,globalIdField,editable,verifiedDefault} from './core.js?v=20261015-template';
import {readXlsx} from './xlsx-read.js';
import {matchImportColumns,parseImport,makePlan,savePlan,normalizeId,BULK_LIMIT} from './bulk.js?v=partial-excel-20261015';
import {workbook} from './xlsx.js';
import {renderExcelEditor} from './excel-editor.js?v=inline-excel-20261015';
export function attachBulk({state,$,run,status,makeTable,loadIds}){
 let plan=null,uploaded=null;
 function context(requireEditing=true){if(!state.meta)throw Error('Select a feature layer first.');if(!globalIdField(state.meta))throw Error('This layer has no Global ID field.');if(requireEditing&&state.meta.isDataVersioned&&(!state.meta.__editContext||!state.meta.__editEnabled))throw Error('Enable direct editing of the verified default version first.');return {api:state.api,url:state.url,meta:structuredClone(state.meta),user:structuredClone(state.user),base:state.baseWhere};}
 async function recordsFor(c,ids){const features=[];for(let i=0;i<ids.length;i+=100){const where=globalIdWhere(c.meta,ids.slice(i,i+100).join(','),c.base);const found=await c.api.ids(c.url,where);if(found.length>ids.length)throw Error('Global ID matching returned an unexpected number of records.');features.push(...await c.api.records(c.url,found,c.meta));}return features;}
 function show(c,draft,source){plan={...draft,url:c.url,version:c.meta.__editContext?.versionName||'',versionGuid:c.meta.__editContext?.versionGuid||'',context:c,source,sent:false};$('batch-title').textContent='Review '+draft.records.length+' device update(s)';$('batch-target').textContent='Target: '+c.url+(plan.version?' · '+plan.version:'')+'. Source: '+source+'. '+draft.inputCount+' input device(s). No data has been written yet.';$('batch-changes').replaceChildren(makeTable(['Global ID','Field','Current','Proposed'],draft.records.flatMap(r=>r.changes.map(change=>[r.globalId,change.field,change.before,change.after]))));$('batch-errors').replaceChildren(makeTable(['Global ID','Validation problem'],draft.errors));$('batch-result').replaceChildren();$('batch-note').textContent=draft.errors.length?'Fix all '+draft.errors.length+' validation problem(s) and prepare a new review.':draft.records.length?'Confirming submits one batch with rollback requested. Concurrent edits are rechecked immediately before saving.':'No changed values were found. Blank Excel cells leave attributes unchanged.';$('batch-save').hidden=!!draft.errors.length||!draft.records.length;$('batch-dialog').showModal();}
 $('batch-close').onclick=()=>$('batch-dialog').close();
 $('batch-open').onclick=()=>run(async()=>{const c=context();if(!state.ids.length||state.ids.length>BULK_LIMIT)throw Error('Search or filter to between 1 and 500 records first.');const fields=visibleFields(c.meta).filter(f=>!['esriFieldTypeOID','esriFieldTypeGlobalID','esriFieldTypeGeometry','esriFieldTypeBlob','esriFieldTypeRaster','esriFieldTypeXML'].includes(f.type)&&f.editable===true&&f.name!==c.meta.typeIdField);$('batch-field').replaceChildren();for(const f of fields)$('batch-field').add(new Option((f.alias||f.name)+' ['+f.name+']',f.name));if(!fields.length)throw Error('No supported editable fields are available.');$('bulk-value-dialog').showModal();});
 $('bulk-value-close').onclick=()=>$('bulk-value-dialog').close();
 $('bulk-value-form').onsubmit=e=>{e.preventDefault();run(async()=>{const c=context(),field=$('batch-field').value;if(!state.ids.length||state.ids.length>BULK_LIMIT)throw Error('Search or filter to 1–500 devices first.');const features=await c.api.records(c.url,[...state.ids],c.meta),gid=globalIdField(c.meta);const value=$('batch-null').checked?'__NULL__':$('batch-value').value===''?'__EMPTY__':$('batch-value').value;const rows=features.map(f=>({globalId:normalizeId(f.attributes[gid.name]),values:{[field]:value}}));const draft=makePlan(rows,features,c.meta,c.user);$('bulk-value-dialog').close();show(c,draft,'Set one field on all matching devices');});};
 $('xlsx-upload').onclick=e=>{if(!state.busy)e.target.value='';};
 $('xlsx-upload').onchange=e=>{const file=e.target.files[0];if(!file)return;const feedback=$('upload-feedback'),preview=$('upload-preview');uploaded=null;$('upload-apply').hidden=true;feedback.classList.remove('error');preview.replaceChildren();feedback.textContent='Selected: '+file.name;if(state.busy){feedback.textContent+=' — another operation is running. Wait, then select the file again.';feedback.classList.add('error');return;}run(async()=>{try{if(file.size>25*1024*1024)throw Error('Excel upload limit is 25 MB.');if(!/\.xlsx$/i.test(file.name))throw Error('Choose an .xlsx workbook. Save older .xls files as .xlsx first.');status('Reading Excel locally…');const sheet=await readXlsx(await file.arrayBuffer());preview.replaceChildren(makeTable(sheet.rows[0]||[],sheet.rows.slice(1,6)));const c=context(false),mapping=matchImportColumns(sheet.rows[0]||[],c.meta);parseImport(sheet.rows,c.meta);uploaded={rows:structuredClone(sheet.rows),mapping,source:file.name+' / '+sheet.name,url:c.url,version:c.meta.__editContext?.versionName||'',versionGuid:c.meta.__editContext?.versionGuid||'',base:c.base,allowed:JSON.stringify(c.meta.__allowedFields)};renderExcelEditor(preview,uploaded.rows,mapping,c.meta);$('upload-apply').hidden=false;feedback.textContent=uploaded.source+' — '+(uploaded.rows.length-1)+' device row(s). Edit or fill in the cells below, then click Apply and submit. Global IDs are locked. No data has been written.';status('Excel ready to edit below the chosen file.');}catch(error){feedback.textContent=file.name+' — '+error.message+' No data was written.';feedback.classList.add('error');throw error;}});};
 $('upload-apply').onclick=()=>run(async()=>{const feedback=$('upload-feedback');try{if(!uploaded)throw Error('Choose an Excel file first.');const c=context();if(c.url!==uploaded.url||(c.meta.__editContext?.versionName||'')!==uploaded.version||(c.meta.__editContext?.versionGuid||'')!==uploaded.versionGuid||c.base!==uploaded.base||JSON.stringify(c.meta.__allowedFields)!==uploaded.allowed)throw Error('Layer, version or filter changed. Upload the Excel again for the selected layer.');const rows=parseImport(uploaded.rows,c.meta),features=await recordsFor(c,rows.map(r=>r.globalId));show(c,makePlan(rows,features,c.meta,c.user),uploaded.source);const heading=document.createElement('h3');heading.textContent='Excel columns matched to this UN layer';$('batch-changes').prepend(heading,makeTable(['Excel column','UN field','UN alias'],uploaded.mapping.filter(Boolean).map(m=>[m.header,m.field.name,m.field.alias||m.field.name])));feedback.classList.remove('error');feedback.textContent=uploaded.source+' — Review opened. Check proposed changes and confirm to save to the same Global IDs.';}catch(error){feedback.textContent=error.message+' No data was written.';feedback.classList.add('error');throw error;}});
 $('template-download').onclick=()=>run(async()=>{const c=context();if(!state.ids.length||state.ids.length>BULK_LIMIT)throw Error('Search or filter to 1–500 devices before downloading an edit template.');const features=await c.api.records(c.url,[...state.ids],c.meta),gid=globalIdField(c.meta);const fields=visibleFields(c.meta).filter(f=>f.name!==gid.name&&features.some(feature=>editable(f,c.meta,c.user,feature.attributes))&&['esriFieldTypeString','esriFieldTypeSmallInteger','esriFieldTypeInteger','esriFieldTypeSingle','esriFieldTypeDouble','esriFieldTypeBigInteger','esriFieldTypeDate','esriFieldTypeGUID'].includes(f.type));const blob=workbook([{name:'Edits',rows:[[gid.name,...fields.map(f=>f.name)],...features.map(f=>[f.attributes[gid.name],...fields.map(field=>f.attributes[field.name])])]},{name:'Instructions',rows:[['Bulk device updates'],['Keep the Global ID column unchanged. Use actual field names. Edit only the Edits worksheet.'],['Blank cells leave values unchanged. __NULL__ explicitly clears a nullable field; __EMPTY__ writes empty text.'],['Use domain codes or exact domain labels. Dates: ISO timestamps or date-formatted Excel cells. Raw exported dates are epoch milliseconds.'],['Maximum 500 device rows. Formulas, unknown headers and duplicate IDs are rejected. The applied WHERE filter controls matching.'],['Upload, review every change, then explicitly confirm. This is an update-only workflow; no new devices or geometries are created.']]},{name:'Field reference',rows:[['Field','Alias','Type','Domain'],...fields.map(f=>[f.name,f.alias,f.type,JSON.stringify(f.domain||null)])]},{name:'Subtype domains',rows:[['Metadata'],[JSON.stringify((c.meta.types||[]).map(type=>({id:type.id,name:type.name,domains:Object.fromEntries(Object.entries(type.domains||{}).filter(([name])=>fields.some(field=>field.name===name)))})))]]}]);const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='REG-TRF-edit-template.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);status('Edit template downloaded for '+features.length+' device(s). Fill it in, then upload for review.');});
 $('batch-save').onclick=()=>run(async()=>{if(!plan||plan.sent)throw Error('Prepare a new batch review before saving.');const c=context();if(c.url!==plan.url||(c.meta.__editContext?.versionName||'')!==plan.version||(c.meta.__editContext?.versionGuid||'')!==plan.versionGuid)throw Error('Selected layer or version changed. Prepare a new review.');let results;try{results=await savePlan(c.api,c.url,c.meta,c.user,plan);}catch(error){$('batch-note').textContent=error.message;throw error;}$('batch-target').textContent=$('batch-target').textContent.replace('No data has been written yet.','Batch submitted; see the per-device results below.');$('batch-save').hidden=true;$('batch-result').replaceChildren(makeTable(['Global ID','Object ID','Result','Details'],results.map(r=>[r.globalId,r.id,r.status,r.detail])));const saved=results.filter(r=>r.status==='Saved').length;$('batch-note').textContent=saved+' / '+results.length+' devices reported saved. Check every result below. Refresh records before retrying any failed or unknown outcome.';status('Bulk save returned: '+saved+' saved, '+(results.length-saved)+' failed or uncertain.');await loadIds();});
}




